/**
 * Static Metro registry for hierarchical monster art:
 *   assets/monsters/{environment}/{mapFolder}/{monsterKey}.png
 * Lookup prefers env/map from the active zone, then fauna from kindId,
 * then any packed match for the slug. Missing art → null (initials fallback).
 *
 * Regenerated by: node scripts/gen-monster-art.js
 */

import { locomotion } from '../../world/gait';

type SpriteModule = number;

/** Game fauna / province id → asset environment folder. */
export const FAUNA_ASSET_ENV: Record<string, string> = {
  plains: 'dongbang',
  mountains: 'nuinon',
  forest: 'rungram',
  swamp: 'damlay',
  beach: 'baibien',
  ocean: 'daiduong',
  tundra: 'banggia',
  savannah: 'thaonguyen',
  volcano: 'nuilua',
  desert: 'samac',
};

/** Asset environment folder → fauna id (reverse of FAUNA_ASSET_ENV). */
const ENV_TO_FAUNA: Record<string, string> = Object.fromEntries(
  Object.entries(FAUNA_ASSET_ENV).map(([fauna, env]) => [env, fauna]),
);

