const KIND_ALIAS: Record<string, string> = {
  frost_toad: 'swamp-mist-toad',
  'swamp-toad': 'swamp-mist-toad',
};

export type MonsterArtContext = {
  /** Fauna/province id (`plains`) or asset env folder (`dongbang`). */
  environment?: string | null;
  /** Map folder such as `map1`. */
  mapFolder?: string | null;
  /** Active field zone id such as `plains:m1`. */
  zoneId?: string | null;
};

export type MonsterArt = {
  source: SpriteModule;
  facesRight: boolean;
  slug: string;
  path: string;
};

export function assetEnvForFauna(faunaOrEnv: string | undefined | null): string | null {
  if (!faunaOrEnv) return null;
  const raw = faunaOrEnv.trim().toLowerCase();
  if (!raw) return null;
  if (FAUNA_ASSET_ENV[raw]) return FAUNA_ASSET_ENV[raw]!;
  if (ENV_TO_FAUNA[raw]) return raw;
  return null;
}

export function faunaFromKindId(kindId: string): string | null {
  const raw = kindId.trim().toLowerCase();
  if (!raw) return null;
  const dash = raw.indexOf('-');
  return dash > 0 ? raw.slice(0, dash) : raw;
}

export function mapFolderFromZoneId(zoneId: string | undefined | null): string | null {
  if (!zoneId) return null;
  const match = /:m(\d+)$/i.exec(zoneId.trim());
  if (!match) return null;
  return `map${Number(match[1])}`;
}

export function environmentFromZoneId(zoneId: string | undefined | null): string | null {
  if (!zoneId) return null;
  const head = zoneId.trim().toLowerCase().split(':')[0] ?? '';
  return assetEnvForFauna(head);
}

function normalizeMapFolder(mapFolder: string | undefined | null): string | null {
  if (!mapFolder) return null;
  const raw = mapFolder.trim().toLowerCase();
  if (!raw) return null;
  if (/^map\d+$/.test(raw)) return raw;
  if (/^m\d+$/.test(raw)) return `map${raw.slice(1)}`;
  if (/^\d+$/.test(raw)) return `map${raw}`;
  return raw;
}

function slugCandidates(kindId: string): string[] {
  const raw = kindId.trim().toLowerCase();
  if (!raw) return [];
  const noPrefix = raw.includes('-') ? raw.slice(raw.lastIndexOf('-') + 1) : raw;
  const compact = raw.replace(/[^a-z0-9]/g, '');
  const mapped = KIND_SLUG[raw];
  return [...new Set([mapped, raw, noPrefix, compact].filter(Boolean) as string[])];
}

/** slug → nested paths that pack that sprite (env/map/slug). */
const PATHS_BY_SLUG: Record<string, string[]> = {};
for (const pathKey of Object.keys(BY_PATH)) {
  const slash = pathKey.lastIndexOf('/');
  const slug = slash >= 0 ? pathKey.slice(slash + 1) : pathKey;
  (PATHS_BY_SLUG[slug] ??= []).push(pathKey);
}

function pickPath(pathKey: string, slug: string, facesKind: string): MonsterArt | null {
  const source = BY_PATH[pathKey];
  if (source == null) return null;
  return { source, facesRight: locomotion(facesKind).facesRight, slug, path: pathKey };
}

/** Resolve battle/field portrait art for a species kindId. */
export function resolveMonsterArt(kindId: string | undefined | null, context?: MonsterArtContext | null): MonsterArt | null {
  if (!kindId) return null;
  const canonical = KIND_ALIAS[kindId] ?? kindId;
  const slugs = slugCandidates(canonical);
  if (!slugs.length) return null;

  const envFromZone = environmentFromZoneId(context?.zoneId);
  const envFromCtx = assetEnvForFauna(context?.environment);
  const envFromKind = assetEnvForFauna(faunaFromKindId(canonical));
  const env = envFromZone ?? envFromCtx ?? envFromKind;

  const mapFromCtx = normalizeMapFolder(context?.mapFolder);
  const mapFromZone = mapFolderFromZoneId(context?.zoneId);
  const mapFolder = mapFromCtx ?? mapFromZone ?? 'map1';

  if (env) {
    for (const slug of slugs) {
      const hit = pickPath(`${env}/${mapFolder}/${slug}`, slug, canonical);
      if (hit) return hit;
    }
    if (mapFolder !== 'map1') {
      for (const slug of slugs) {
        const hit = pickPath(`${env}/map1/${slug}`, slug, canonical);
        if (hit) return hit;
      }
    }
  }

  for (const slug of slugs) {
    const preferred = env ? `${env}/` : null;
    const keys = [...(PATHS_BY_SLUG[slug] ?? [])];
    keys.sort((a, b) => {
      const ap = preferred && a.startsWith(preferred) ? 0 : 1;
      const bp = preferred && b.startsWith(preferred) ? 0 : 1;
      return ap - bp || a.localeCompare(b);
    });
    for (const key of keys) {
      const hit = pickPath(key, slug, canonical);
      if (hit) return hit;
    }
  }

  for (const slug of slugs) {
    const source = BY_FLAT_SLUG[slug];
    if (source == null) continue;
    return { source, facesRight: locomotion(canonical).facesRight, slug, path: slug };
  }
  return null;
}

export function hasMonsterArt(kindId: string | undefined | null, context?: MonsterArtContext | null): boolean {
  return resolveMonsterArt(kindId, context) != null;
}

export function monsterInitials(name: string): string {
  const cleaned = name.trim();
  if (!cleaned) return '?';
  const parts = cleaned.split(/\s+/).filter(Boolean);
  if (parts.length >= 2) {
    return `${parts[0]![0] ?? ''}${parts[1]![0] ?? ''}`.toUpperCase();
  }
  return cleaned.slice(0, 2).toUpperCase();
}
